function help=analysisHelpText(topic)
%ANALYSISHELPTEXT Explain white roles without changing analysis conventions.
% CIELAB reference: https://cie.co.at/eilvterm/17-23-076
% Bradford and object-colour implementation: docs/session/illumination.md.
% This is operating help; calculations and their guards remain in analysis.
% Fernando Voltolini de Azambuja, 2026.
switch topic
    case 'compare'
        help.title='Whites for comparison';
        help.headings={'Samples and Lab white','Choosing a white','White Y','Instrument calibration'};
        help.paragraphs={ ...
            'A (ref.) and B (test) are the samples being compared. Lab white is a separate white used for both CIELAB values and their ΔE00 difference.', ...
            'For a display-relative comparison, choose a white reading from that display and setup. For surface samples under a lamp, choose a white reference measured under the same illumination, geometry and settings. A measured-white selection uses its full XYZ directly, including Y. For a specified target white, choose D50, D65 or A and enter White Y on the readings'' XYZ scale.', ...
            'White Y is editable for presets only. Keep 100 when the target white has Y = 100 on that scale; a target white at 300 cd/m² needs 300. A common scale change of samples and white leaves Lab unchanged; normalizing each sample separately would remove lightness differences.', ...
            'Instrument reference calibration is part of preparing the instrument. Selecting a Lab white does not perform calibration or remove illumination from a spectrum.'};
        help.details={ ...
            'CIELAB uses X/Xn, Y/Yn and Z/Zn. Both samples must use the same reference white and compatible XYZ conventions.', ...
            'Preset White Y starts at 100 and is editable. A measured-white selection uses its XYZ directly and hides this editor. The software leaves measured XYZ unchanged. An operator scale declaration does not override known incompatible conventions.', ...
            'CIE S 017:2020, term 17-23-076: https://cie.co.at/eilvterm/17-23-076'};
    case 'color'
        help.title='Whites and light in Color views';
        help.headings={'Chromatic adaptation','Measured object reference','Relight with','Instrument calibration'};
        help.paragraphs={ ...
            'Source white describes the adapting white for the measured color. To white describes the intended adapting white. Choose a preset or a reading deliberately measured as white. Adaptation models corresponding color coordinates; it does not predict a material''s spectrum under another light.', ...
            'Reflectance / relight uses a reflective object and a white object reference measured under matching illumination, geometry and settings. Load the reference''s spectral reflectance data. Assume ideal white (R = 1) instead gives a relative spectral ratio.', ...
            'The target is an illuminant spectral power distribution: D50, D65, A, or a measured light spectrum on the compatible grid. A white-tile spectrum also contains the tile''s reflectance, so it is not automatically the illuminating light.', ...
            'Follow the instrument''s preparation and calibration procedure before acquisition. Its calibration reference, the measured object reference and the Lab comparison white have different roles.'};
        help.details={ ...
            'Chromatic adaptation uses full linear Bradford. Both white vectors are normalized to Y = 1; sample XYZ is not separately normalized. The measured spectrum stays measured.', ...
            'The object calculation estimates a directional spectral reflectance factor: sample radiance / reference radiance × reference reflectance for a nonfluorescent reflective object. Matching grids, quantities, common numerical scale and setup remain required.', ...
            'Derived Color views are separate from acquired readings and Compare. Apply view does not acquire or edit a measurement.', ...
            'Implementation and sources: docs/session/illumination.md; docs/colorimetry/science.md.'};
    otherwise
        error('Measurement:AnalysisHelp','Unknown analysis help topic.');
end
end
